// pnpm --filter @crewarcade/server db:migrate
// Applies the SQL migrations in apps/server/drizzle/ (generated by `db:generate`) in order.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import { loadConfig } from '../config';
import { createDb } from './client';

const config = loadConfig();
const { db, close } = createDb(config.DATABASE_URL, { max: 1 });
// src/db/migrate.ts (tsx) and dist/migrate.js (bundled) sit at different depths.
const here = path.dirname(fileURLToPath(import.meta.url));
const migrationsFolder = [path.resolve(here, '..', '..', 'drizzle'), path.resolve(here, '..', 'drizzle')].find(d => fs.existsSync(path.join(d, 'meta')));
if (!migrationsFolder) throw new Error('drizzle/ migrations folder not found');
try {
  await migrate(db, { migrationsFolder });
  console.log(`Migrations applied from ${path.relative(process.cwd(), migrationsFolder) || migrationsFolder}`);
} finally {
  await close();
}
